cd /code && python - <<'PY'
import nbformat, json
nb=nbformat.read('PerformanveEval.ipynb', as_version=4)
print('cells', len(nb.cells))
for i,c in enumerate(nb.cells):
    if c.cell_type=='markdown':
        txt=' '.join(c.source.split())
        if '44' in txt or 'mapping' in txt.lower() or 'execution time' in txt.lower():
            print('\nMD',i,txt[:500])
    else:
        src=c.source
        if '44' in src or 'mapping' in src.lower() or 'execution time' in src.lower():
            print('\nCODE',i,src[:700])
